@@ -0,0 +1,63 @@
+import { invoke } from '@tauri-apps/api/core';
+import { z } from 'zod';
+import {
+  NewObservationSchema,
+  ObservationSchema,
+  SiteSchema,
+  type NewObservation,
+  type Observation,
+  type Site,
+} from './schemas';
+
+export class IpcContractError extends Error {
+  readonly command: string;
+  readonly issues: string[];
+
+  constructor(command: string, issues: string[]) {
+    const detail = issues.length > 0 ? issues.join('; ') : 'invalid payload';
+    super(`${command}: ${detail}`);
+    this.name = 'IpcContractError';
+    this.command = command;
+    this.issues = issues.length > 0 ? issues : ['invalid payload'];
+  }
+}
+
+function check<T>(command: string, schema: z.ZodType<T>, value: unknown): T {
+  const result = schema.safeParse(value);
+  if (!result.success) {
+    const issues = result.error.issues.map((issue) => {
+      const path = issue.path.map(String).join('.');
+      return path ? `${path}: ${issue.message}` : issue.message;
+    });
+    throw new IpcContractError(command, issues);
+  }
+  return result.data;
+}
+
+const RFC3339 = z.iso.datetime({ offset: true });
+
+export async function getSite(siteId: number): Promise<Site> {
+  const raw: unknown = await invoke('get_site', { siteId });
+  return check('get_site', SiteSchema, raw);
+}
+
+export async function listObservations(siteId: number, since?: string): Promise<Observation[]> {
+  if (since !== undefined) {
+    const parsed = RFC3339.safeParse(since);
+    if (!parsed.success) {
+      throw new IpcContractError('list_observations', ['since: must be an RFC 3339 timestamp']);
+    }
+  }
+  const args: Record<string, unknown> = { siteId };
+  if (since !== undefined) {
+    args.since = since;
+  }
+  const raw: unknown = await invoke('list_observations', args);
+  return check('list_observations', z.array(ObservationSchema), raw);
+}
+
+export async function recordObservation(input: NewObservation): Promise<Observation> {
+  const parsed = check('record_observation', NewObservationSchema, input);
+  const raw: unknown = await invoke('record_observation', { input: parsed });
+  return check('record_observation', ObservationSchema, raw);
+}
