+import { useEffect, useState } from 'react';
+import { describeVaultError, isVaultError, listLots, withdraw, type Lot } from './api';
+
+function errorMessage(error: unknown): string {
+  return isVaultError(error) ? describeVaultError(error) : 'Unexpected error';
+}
+
+export function SeedVaultPanel({ step = 10 }: { step?: number }) {
+  const [lots, setLots] = useState<Lot[] | null>(null);
+  const [loading, setLoading] = useState(true);
+  const [alert, setAlert] = useState<string | null>(null);
+  const [pending, setPending] = useState<ReadonlySet<string>>(new Set());
+
+  useEffect(() => {
+    let active = true;
+    listLots().then(
+      (result) => {
+        if (active) {
+          setLots(result);
+          setLoading(false);
+        }
+      },
+      (error: unknown) => {
+        if (active) {
+          setAlert(errorMessage(error));
+          setLoading(false);
+        }
+      },
+    );
+    return () => {
+      active = false;
+    };
+  }, []);
+
+  async function handleWithdraw(code: string): Promise<void> {
+    setPending((prev) => new Set(prev).add(code));
+    try {
+      const updated = await withdraw(code, step);
+      setLots((prev) => prev?.map((lot) => (lot.code === updated.code ? updated : lot)) ?? prev);
+      setAlert(null);
+    } catch (error: unknown) {
+      setAlert(errorMessage(error));
+    } finally {
+      setPending((prev) => {
+        const next = new Set(prev);
+        next.delete(code);
+        return next;
+      });
+    }
+  }
+
+  return (
+    <section>
+      {alert !== null && <p role="alert">{alert}</p>}
+      {loading && <p>Loading lots…</p>}
+      {!loading && lots !== null && lots.length === 0 && <p>The vault is empty</p>}
+      {lots !== null && lots.length > 0 && (
+        <table>
+          <thead>
+            <tr>
+              <th>Code</th>
+              <th>Weight</th>
+              <th>Action</th>
+            </tr>
+          </thead>
+          <tbody>
+            {lots.map((lot) => {
+              const busy = pending.has(lot.code);
+              return (
+                <tr key={lot.code}>
+                  <td>{lot.code}</td>
+                  <td>{`${lot.grams} g`}</td>
+                  <td>
+                    <button
+                      type="button"
+                      aria-label={`Withdraw ${step} g from ${lot.code}`}
+                      disabled={busy || lot.grams < step}
