+import { Channel, invoke } from '@tauri-apps/api/core';
+
+export interface ScanProgress {
+  bytes: number;
+  chunks: number;
+}
+
+interface StreamSummary {
+  bytes: number;
+  chunks: number;
+}
+
+export class ScanIncompleteError extends Error {
+  readonly expectedChunks: number;
+  readonly receivedChunks: number;
+
+  constructor(message: string, expectedChunks: number, receivedChunks: number) {
+    super(message);
+    this.name = 'ScanIncompleteError';
+    this.expectedChunks = expectedChunks;
+    this.receivedChunks = receivedChunks;
+  }
+}
+
+/**
+ * Streams a scan from the archive as raw binary chunks and resolves with the
+ * complete contents. Backend errors are re-thrown unchanged.
+ */
+export async function fetchScan(
+  name: string,
+  chunkSize: number,
+  options: { onProgress?: (progress: ScanProgress) => void; timeoutMs?: number } = {},
+): Promise<Uint8Array> {
+  const { onProgress, timeoutMs = 5000 } = options;
+  const parts: Uint8Array[] = [];
+  const listeners = new Set<() => void>();
+  let bytes = 0;
+  let chunks = 0;
+
+  const onChunk = new Channel<ArrayBuffer>();
+  onChunk.onmessage = (message) => {
+    const part = new Uint8Array(message);
+    parts.push(part);
+    bytes += part.byteLength;
+    chunks += 1;
+    onProgress?.({ bytes, chunks });
+    for (const listener of [...listeners]) {
+      listener();
+    }
+  };
+
+  const summary = await invoke<StreamSummary>('stream_scan', { name, chunkSize, onChunk });
+
+  // Channel messages may still be in flight once the command has resolved.
+  const arrived = await new Promise<boolean>((resolve) => {
+    const settle = (ok: boolean) => {
+      clearTimeout(timer);
+      listeners.delete(check);
+      resolve(ok);
+    };
+    const check = () => {
+      if (chunks >= summary.chunks) {
+        settle(true);
+      }
+    };
+    const timer = setTimeout(() => {
+      settle(false);
+    }, timeoutMs);
+    listeners.add(check);
+    check();
+  });
+
+  if (!arrived || chunks !== summary.chunks) {
+    throw new ScanIncompleteError(
+      `scan ${name} incomplete: received ${chunks} of ${summary.chunks} chunks`,
+      summary.chunks,
+      chunks,
+    );
+  }
+  if (bytes !== summary.bytes) {
+    throw new ScanIncompleteError(
+      `scan ${name} incomplete: received ${bytes} of ${summary.bytes} bytes`,
+      summary.chunks,
+      chunks,
+    );
+  }
+
+  const out = new Uint8Array(bytes);
+  let offset = 0;
+  for (const part of parts) {
+    out.set(part, offset);
+    offset += part.byteLength;
+  }
+  return out;
+}
